class T:
    def __init__(self, v):
        self.v, self.l, self.r = v, None, None

def insert(t, v):
    if not t:
        return T(v)
    if v < t.v:
        t.l = insert(t.l, v)
    else:
        t.r = insert(t.r, v)
    return t

def inorder(t):
    return inorder(t.l) + [t.v] + inorder(t.r) if t else []

def height(t):
    return 1 + max(height(t.l), height(t.r)) if t else 0

root = None
for v in [5, 2, 8, 1, 3]:
    root = insert(root, v)
print(inorder(root), height(root))

