from collections import deque
g = {1: [3, 2], 2: [5], 3: [4], 4: [5], 5: []}
seen = {1}
q = deque([1])
order = []
while q:
    u = q.popleft()
    order.append(u)
    for v in g[u]:
        if v not in seen:
            seen.add(v)
            q.append(v)
