import heapq
g = {"A": [("B", 4), ("C", 1)], "B": [("D", 1)], "C": [("B", 2), ("D", 5)], "D": []}
dist = {"A": 0}
h = [(0, "A")]
while h:
    d, u = heapq.heappop(h)
    if d > dist.get(u, 99):
        continue
    for v, w in g[u]:
        nd = d + w
        if nd < dist.get(v, 99):
            dist[v] = nd
            heapq.heappush(h, (nd, v))
print(dist["B"], dist["D"])

def solve(n):
    cols, d1, d2 = set(), set(), set()
    def go(r):
        if r == n:
            return 1
        total = 0
        for c in range(n):
            if c in cols or r - c in d1 or r + c in d2:
                continue
            cols.add(c); d1.add(r - c); d2.add(r + c)
            total += go(r + 1)
            cols.remove(c); d1.remove(r - c); d2.remove(r + c)
        return total
    return go(0)

print(solve(4), solve(5), solve(6))

